using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests
    {
        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student 'Alice Doe' has been created")]
        [InlineData(EntityOperation.UPDATE, "Student 'Alice Doe' has been updated")]
        [InlineData(EntityOperation.DELETE, "Student 'Alice Doe' has been deleted")]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", "Alice Doe", operation, "TestUser");

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal(operation.ToString(), notification.Operation);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student (ID: 42) has been created")]
        [InlineData(EntityOperation.UPDATE, "Student (ID: 42) has been updated")]
        [InlineData(EntityOperation.DELETE, "Student (ID: 42) has been deleted")]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage(EntityOperation operation, string expectedMessage)
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "42", operation);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            using var service = new NotificationService();

            service.SendNotification("Course", "101", "Intro to CS", EntityOperation.CREATE, null);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            using var service = new NotificationService();

            var notification = service.ReceiveNotification();

            Assert.Null(notification);
        }

        [Fact]
        public void SendAndReceive_MultipleNotifications_ReturnsInFifoOrder()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
            service.SendNotification("Department", "3", "Third", EntityOperation.DELETE);

            var first = service.ReceiveNotification();
            var second = service.ReceiveNotification();
            var third = service.ReceiveNotification();

            Assert.Equal("1", first.EntityId);
            Assert.Equal("2", second.EntityId);
            Assert.Equal("3", third.EntityId);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            using var service = new NotificationService();

            // MarkAsRead is a no-op but should not throw
            var exception = Record.Exception(() => service.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Helpers
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_MiddlePage_HasBothNavigation()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.True(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_LastPage_HasNoPreviousPageOnly()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.True(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_NoNavigation()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<string> { "a", "b", "c" };

            var result = new PaginatedList<string>(items, 30, 2, 10);

            Assert.Equal(3, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }
    }
}

